#!/usr/bin/env python3
"""Generate the DROM selector cache (selectors.h) from selectors.txt.

Usage: gen_selectors.py selectors.txt out/selectors.h
Called by build_eth.sh at build time; deterministic (sorted by sig).

Each line of selectors.txt is a canonical signature (no spaces). Validation
here is syntactic (shape, known type names); semantic verification (this sig
really has this selector) is scripts/verify_selectors.py against 4byte, plus
gate-1 fuzz over table entries on every run.
"""

import re
import sys
from pathlib import Path

from eth_hash.auto import keccak

ATOMS = {"address", "bool", "string", "bytes"}
ATOMS |= {f"uint{n}" for n in range(8, 257, 8)} | {f"int{n}" for n in range(8, 257, 8)}
ATOMS |= {f"bytes{n}" for n in range(1, 33)}


def split_top(s: str) -> list[str]:
    parts, depth, cur = [], 0, ""
    for c in s:
        if c == "(":
            depth += 1
        elif c == ")":
            depth -= 1
            if depth < 0:
                return []
        if c == "," and depth == 0:
            parts.append(cur)
            cur = ""
        else:
            cur += c
    parts.append(cur)
    return parts if depth == 0 else []


def valid_type(t: str) -> bool:
    # strip array suffixes
    while t.endswith("]"):
        lb = t.rfind("[")
        if lb < 0 or any(c not in "0123456789" for c in t[lb + 1:-1]):
            return False
        t = t[:lb]
    if t in ATOMS:
        return True
    if t.startswith("(") and t.endswith(")") and len(t) >= 2:
        inner = split_top(t[1:-1])
        return bool(inner) and all(valid_type(p) for p in inner)
    return False


def check_sig(sig: str) -> str | None:
    if any(c.isspace() for c in sig):
        return "whitespace"
    m = re.fullmatch(r"([A-Za-z_][A-Za-z0-9_]*)\((.*)\)", sig, re.S)
    if not m:
        return "shape"
    _, inside = m.group(1), m.group(2)
    if inside == "":
        return None
    for p in split_top(inside):
        if not valid_type(p):
            return f"type {p!r}"
    return None


def main() -> int:
    src, dst = Path(sys.argv[1]), Path(sys.argv[2])
    sigs = [l.strip() for l in src.read_text().splitlines()
            if l.strip() and not l.strip().startswith("#")]
    if len(set(sigs)) != len(sigs):
        dups = sorted({s for s in sigs if sigs.count(s) > 1})
        print(f"FATAL: duplicate signatures: {dups}", file=sys.stderr)
        return 1
    for s in sigs:
        err = check_sig(s)
        if err:
            print(f"FATAL: {s!r}: {err}", file=sys.stderr)
            return 1
    rows = [(s, keccak(s.encode()).hex()) for s in sorted(sigs)]
    out = ["// Generated by gen_selectors.py from selectors.txt; do not edit.",
           "#pragma once", "#include <stdint.h>",
           "typedef struct { const char *sig; uint8_t hash[32]; } selector_entry_t;",
           "static const selector_entry_t selector_table[] = {"]
    for s, h in rows:
        bs = ",".join(f"0x{h[i:i+2]}" for i in range(0, 64, 2))
        out.append(f'    {{"{s}", {{{bs}}}}},')
    out.append("};")
    out.append("#define SELECTOR_COUNT (sizeof(selector_table)/sizeof(selector_table[0]))")
    dst.write_text("\n".join(out) + "\n")
    print(f"{dst}: {len(rows)} entries")
    return 0


if __name__ == "__main__":
    sys.exit(main())
